import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// BULLETPROOF IMMUTABLE CLASS
public final class ImmutableUserProfile {
    private final String username;
    private final List<String> roles;

    public ImmutableUserProfile(String username, List<String> roles) {
        this.username = username;
        // RULE 4: Defensive copy on construction
        this.roles = (roles != null) ? new ArrayList<>(roles) : new ArrayList<>();
    }

    public String getUsername() { return username; }

    // RULE 5: Defensive copy or unmodifiable view on access
    public List<String> getRoles() {
        return Collections.unmodifiableList(roles);
    }
}

public class LeakDemo {
    public static void main(String[] args) {
        List<String> mutableRoles = new ArrayList<>();
        mutableRoles.add("USER");

        ImmutableUserProfile profile = new ImmutableUserProfile("alice", mutableRoles);

        // Attempt 1: Modifying external list doesn't corrupt profile!
        mutableRoles.add("ADMIN"); // Outside modification
        System.out.println("Profile roles: " + profile.getRoles()); // Still only [USER]!

        // Attempt 2: Modifying returned list throws UnsupportedOperationException!
        try {
            profile.getRoles().add("SUPER_ADMIN");
        } catch (UnsupportedOperationException e) {
            System.out.println("Caught expected rejection: Cannot modify unmodifiable list!");
        }
    }
}

