import java.util.List;

// Modern Java Record: inherently final with private final components
public record ImmutableAuditRecord(String eventId, String actor, List<String> tags) {
    // Compact constructor for validation and defensive copying
    public ImmutableAuditRecord {
        if (eventId == null || actor == null) {
            throw new IllegalArgumentException("Identifiers cannot be null");
        }
        // Defensive copy for mutable collections
        tags = (tags != null) ? List.copyOf(tags) : List.of();
    }
}

public class RecordDemo {
    public static void main(String[] args) {
        ImmutableAuditRecord rec1 = new ImmutableAuditRecord("evt-101", "admin", List.of("security", "audit"));
        System.out.println("Record toString: " + rec1);
        System.out.println("Actor:           " + rec1.actor());
        System.out.println("Tags:            " + rec1.tags());
    }
}

