import java.util.Arrays;

public final class Transcript {
    private final String studentName;
    private final int[] grades;

    public Transcript(String name, int[] grades) {
        this.studentName = name;
        this.grades = (grades != null) ? grades.clone() : new int[0];
    }
    public String getStudentName() { return studentName; }
    public int[] getGrades() {
        return grades.clone();
    }

    public static void main(String[] args) {
        int[] original = new int[]{90, 85, 95};
        Transcript t = new Transcript("Alice", original);
        original[0] = 0;
        System.out.println("Transcript grade 0: " + t.getGrades()[0]);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class CartSnapshot {
    private final String customerId;
    private final List<String> items;

    public CartSnapshot(String customerId, List<String> items) {
        this.customerId = customerId;
        this.items = (items != null) ? new ArrayList<>(items) : new ArrayList<>();
    }
    public String getCustomerId() { return customerId; }
    public List<String> getItems() {
        return Collections.unmodifiableList(items);
    }
    public CartSnapshot withAddedItem(String newItem) {
        List<String> nextItems = new ArrayList<>(this.items);
        nextItems.add(newItem);
        return new CartSnapshot(this.customerId, nextItems);
    }
}

public class CartApp {
    public static void main(String[] args) {
        List<String> items = new ArrayList<>();
        items.add("Book");
        items.add("Pen");

        CartSnapshot snap1 = new CartSnapshot("cust-1", items);
        items.add("Notebook");

        CartSnapshot snap2 = snap1.withAddedItem("Ruler");
        System.out.println("snap1 items: " + snap1.getItems());
        System.out.println("snap2 items: " + snap2.getItems());
    }
}

final class SecurityPolicy {
    private final String policyName;
    private final int minPasswordLength;
    private final boolean requireMfa;

    public SecurityPolicy(String policyName, int minPasswordLength, boolean requireMfa) {
        if (minPasswordLength < 8) {
            throw new IllegalArgumentException("Password length must be at least 8");
        }
        this.policyName = policyName;
        this.minPasswordLength = minPasswordLength;
        this.requireMfa = requireMfa;
    }

    public String getPolicyName() { return policyName; }
    public int getMinPasswordLength() { return minPasswordLength; }
    public boolean isRequireMfa() { return requireMfa; }

    public boolean checkPassword(String pwd) {
        return pwd != null && pwd.length() >= minPasswordLength;
    }
}

public class SecurityApp {
    public static void main(String[] args) {
        SecurityPolicy policy = new SecurityPolicy("EnterpriseStandard", 12, true);
        System.out.println("weak: " + policy.checkPassword("weak"));
        System.out.println("strong: " + policy.checkPassword("SuperSecretPassword2026"));
    }
}

