import java.util.ArrayList;
import java.util.List;

public record AuditLog(String traceId, String user, List<String> actions) {
    public AuditLog {
        if (traceId == null || user == null) {
            throw new IllegalArgumentException("traceId and user cannot be null");
        }
        actions = (actions != null) ? List.copyOf(actions) : List.of();
    }

    public boolean containsAction(String act) {
        return actions.contains(act);
    }

    public static void main(String[] args) {
        List<String> rawActions = new ArrayList<>();
        rawActions.add("LOGIN");
        rawActions.add("VIEW_DASHBOARD");

        AuditLog log = new AuditLog("tr-999", "alice", rawActions);
        rawActions.add("DELETE_DATABASE");

        System.out.println("Log trace: " + log.traceId());
        System.out.println("Contains DELETE_DATABASE: " + log.containsAction("DELETE_DATABASE"));
        System.out.println("Total actions: " + log.actions().size());
    }
}
